// Shows the right variant of a screenshot (#779).
//
// A page writes a screenshot as plain Markdown, by motif and without language
// or theme: `![Alt text](screenshots/overview.webp)`. The files exist only in
// variants, public/screenshots/<motif>.<lang>.<theme>.webp, generated by
// scripts/screenshots.mjs. This plugin picks the page's language from where
// the page lies (src/content/docs/de/ is German) and puts both themes in;
// src/styles/theme.css hides the one that does not match the page's
// data-theme. Starlight lets the reader choose the theme, so a
// prefers-color-scheme <picture> would be wrong whenever that choice differs
// from the system's.
//
// A missing variant stops the build instead of leaving a broken image.
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import sharp from 'sharp';

const SCREENSHOT = /^(?:\.\/)?screenshots\/([a-z0-9-]+)\.webp$/;
const PUBLIC_DIR = fileURLToPath(new URL('../../public/screenshots/', import.meta.url));
/** The screenshots are taken at this device scale factor; see scripts/screenshots.mjs. */
const SCALE = 2;

function escapeHtml(text) {
  return String(text).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
}

function localeOf(file) {
  const where = (file.path ?? file.history?.[0] ?? '').split('\\').join('/');
  return /\/src\/content\/docs\/de\//.test(where) ? 'de' : 'en';
}

async function variant(motif, locale, theme) {
  const name = `${motif}.${locale}.${theme}.webp`;
  const path = `${PUBLIC_DIR}${name}`;
  if (!existsSync(path)) {
    throw new Error(`Screenshot variant missing: public/screenshots/${name} — run \`npm run screenshots -- ${motif}\``);
  }
  const { width, height } = await sharp(path).metadata();
  return { src: `/screenshots/${name}`, width: Math.round(width / SCALE), height: Math.round(height / SCALE) };
}

async function toHtml(node, locale) {
  const [, motif] = node.url.match(SCREENSHOT);
  const alt = escapeHtml(node.alt ?? '');
  const images = await Promise.all(['light', 'dark'].map(async (theme) => {
    const { src, width, height } = await variant(motif, locale, theme);
    // On a phone the window is small; a tap opens it at full size.
    return `<a class="screenshot-link screenshot--${theme}" href="${src}">`
      + `<img class="screenshot" src="${src}" alt="${alt}" width="${width}" height="${height}" loading="lazy" decoding="async">`
      + '</a>';
  }));
  return { type: 'html', value: images.join('') };
}

function collect(node, found) {
  if (!Array.isArray(node.children)) return;
  node.children.forEach((child, index) => {
    if (child.type === 'image' && SCREENSHOT.test(child.url)) found.push({ parent: node, index, child });
    else collect(child, found);
  });
}

export default function remarkScreenshots() {
  return async (tree, file) => {
    const found = [];
    collect(tree, found);
    const locale = localeOf(file);
    for (const { parent, index, child } of found) {
      parent.children[index] = await toHtml(child, locale);
    }
  };
}
